"""Self-contained review of the identified palette, including third-party credits."""
from pathlib import Path
import argparse,json,base64,html
R=Path(__file__).resolve().parents[1];p=argparse.ArgumentParser();p.add_argument('--source',type=Path,default=R);p.add_argument('--output',type=Path);a=p.parse_args();root=a.source;meta=json.loads((root/'src/audio/provenance.json').read_text())['sources'];sections=[];sfx=[]
def e(v):return html.escape(str(v))
def audio(path,loop=False):return '<audio controls preload="none" '+('loop ' if loop else '')+'src="data:audio/mpeg;base64,'+base64.b64encode(path.read_bytes()).decode()+'"></audio>'
names={'underpass':'機房走廊','rush':'精英壓力','hit':'普通命中','hit_metal':'金屬命中','hit_wood':'木箱命中','boss':'首領','ph_key':'裝置按鍵'}
for r in meta:
 key=Path(r['asset']).stem;title=r.get('title',names.get(key.removeprefix('sf_'),key));body='<h2>'+e(title)+'</h2><p>'+e(r.get('authorship',''))+' · '+e(r.get('license','Project-original'))+'</p><p>'+str(round(r['duration'],2))+'秒'+(' · '+str(r['bpm'])+' BPM' if 'bpm' in r else '')+(' · '+str(r['bars'])+'小節' if 'bars' in r else '')+'</p>'+audio(root/'src/audio'/r['asset'],r['kind']=='music')
 if r.get('sourceUrl'):body+='<p><a href="'+e(r['sourceUrl'])+'" target="_blank" rel="noopener">作者來源</a></p>'
 old=root/'assets/audio-legacy'/r['asset']
 if r['kind']=='music' and old.exists():body+='<details><summary>歷史v0.64封存曲（非現行）</summary>'+audio(old,True)+'</details>'
 (sections if r['kind']=='music' else sfx).append('<article>'+body+'</article>')
page='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hello, Static! 音訊試聽</title><style>*{box-sizing:border-box}body{margin:0;background:#e8eaf6;color:#24344c;font:16px/1.6 system-ui}header,main{max-width:1200px;margin:auto;padding:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:16px}article{min-width:0;padding:16px;background:white;border:1px solid #9ba9ca}h2{font-size:20px}audio{width:100%}p{overflow-wrap:anywhere}button{min-height:44px;padding:10px}a{color:#274e98}</style><header><h1>Hello, Static! 配樂與音效</h1><p>目前候選的6首配樂與48音效，另有3首歷史對照。授權曲與原創音色混合；完整署名見src/audio/LICENSES.md。這是素材試聽，遊戲另用雙deck淡換／優先權／音量控制。主觀與真機驗收不會自動填通過。</p><button id="stop">全部停止</button><label>音量 <input id="volume" type="range" min="0" max="1" step="0.05" value="0.6"></label></header><main><h2>配樂</h2><div class="grid">'''+''.join(sections)+'''</div><h2>音效</h2><div class="grid">'''+''.join(sfx)+'''</div><p>Zane Little Music、The Cynic Project／cynicmusic.com／pixelsphere.org、iamoneabe、dant-e、Nostromo、Kenney：CC0來源已記錄。其餘原創部分屬Game-Lab。未採樣Ice Cream.mp4、Dream Logic或Dorephin Shopping Center錄音。</p></main><script>const all=[...document.querySelectorAll('audio')];all.forEach(a=>{a.volume=.6;a.addEventListener('play',()=>all.forEach(b=>{if(a!==b)b.pause()}))});document.getElementById('stop').onclick=()=>all.forEach(a=>{a.pause();a.currentTime=0});document.getElementById('volume').oninput=e=>all.forEach(a=>a.volume=+e.target.value);</script></html>'''
out=a.output or root/'dist/street-audio-review.html';out.write_text(page);print('Built review:',len(sections),'music,',len(sfx),'sfx')
